Check(!LocalReminderPlan.IsValid(540,540,60) && !LocalReminderPlan.IsValid(-1,1320,60) && !LocalReminderPlan.IsValid(540,1320,0), "Invalid reminder windows and repetition rates are rejected");
var reminderDstZone = TimeZoneInfo.FindSystemTimeZoneById("Eastern Standard Time");
var reminderDst = LocalReminderPlan.Next(new DateTimeOffset(2026,3,8,1,45,0,TimeSpan.FromHours(-5)),reminderDstZone,90,270,60);
Check(reminderDst.Hour == 3 && reminderDst.Offset == TimeSpan.FromHours(-4), "Reminders skip nonexistent spring DST clock times");
Check(MushafPageArchive.GroupStart(1) == 1 && MushafPageArchive.GroupStart(10) == 1 && MushafPageArchive.GroupStart(11) == 11 && MushafPageArchive.GroupStart(604) == 601, "Mushaf archive page boundaries select the correct group");
foreach (var page in new[] { 1, 3, 604 })
{
    using var grouped = File.OpenRead(Path.Combine(AppContext.BaseDirectory, $"{MushafPageArchive.GroupStart(page):000}.bin.br"));
    var actual = MushafPageArchive.Read(grouped, page);
    using var originalFile = File.OpenRead(Path.Combine(AppContext.BaseDirectory, $"{page:000}.svg.br"));
    using var originalDecoded = new System.IO.Compression.BrotliStream(originalFile, System.IO.Compression.CompressionMode.Decompress);
    using var originalReader = new StreamReader(originalDecoded);
    Check(actual == originalReader.ReadToEnd(), $"Grouped page {page} restores the original SVG character for character");
}
var wrongArchive = false;
try { using var file = File.OpenRead(Path.Combine(AppContext.BaseDirectory, "001.bin.br")); MushafPageArchive.Read(file, 604); } catch (InvalidDataException) { wrongArchive = true; }
Check(wrongArchive, "A mismatched page group cannot display the wrong Quran page");
var outsideArchive = false;
try { using var empty = new MemoryStream(); MushafPageArchive.Read(empty, 605); } catch (ArgumentOutOfRangeException) { outsideArchive = true; }
Check(outsideArchive, "Archive reader rejects out-of-range page requests");
using var quarterFile = File.OpenRead(Path.Combine(AppContext.BaseDirectory, "quran-metadata.xml"));
var quarters = QuranPartitions.Read(quarterFile);
Check(quarters.Count == 240 && quarters.GroupBy(q => q.Juz).Count() == 30 && quarters.GroupBy(q => q.Juz).All(g => g.Count() == 8), "Quran index has all 240 quarters, eight per juz");
Check(quarters[0] == new QuarterStart(1, 1, 1) && quarters[1] == new QuarterStart(2, 2, 26) && quarters[2] == new QuarterStart(3, 2, 44), "Quarter starts match the source metadata");
Check(quarters.All(q => verses.Any(v => v.Surah == q.Surah && v.Ayah == q.Ayah && v.Juz == q.Juz)), "Every quarter points to an existing verse in its correct juz");
Check(quarters.Select(q => verses.First(v => v.Surah == q.Surah && v.Ayah == q.Ayah).Number).SequenceEqual(quarters.Select(q => verses.First(v => v.Surah == q.Surah && v.Ayah == q.Ayah).Number).Order()), "Quarter navigation follows Quran order");
Check(HijriDateText.Months.Length == 12 && HijriDateText.Months[8] == "رمضان" && HijriDateText.Format(new DateTime(2026,11,5)).Contains("هـ"), "Hijri dates use named Arabic months");
var darkMarkup = MushafMarkup.Build("<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'><path class='ayahPolygon' surah='1' ayah='1' d='M0 0Z'/></svg>", 2);
Check(darkMarkup.Contains("style=\"background:#101f1c\"") && darkMarkup.Contains("data-theme=\"2\""), "Night palette is present in the initial document before first paint");
var preparedOne = MushafMarkup.PrepareSvg("<svg xmlns='http://www.w3.org/2000/svg'><path class='ayahPolygon' surah='1' ayah='1' d='M0 0Z'/></svg>", 1);
var preparedTwo = MushafMarkup.PrepareSvg("<svg xmlns='http://www.w3.org/2000/svg'><path class='ayahPolygon' surah='1' ayah='1' d='M0 0Z'/></svg>", 2);
Check(preparedOne.Contains("p1_alm_clip") && !preparedOne.Contains("url(#alm_") && preparedTwo.Contains("p2_alm_clip"), "Adjacent page SVG clip and filter IDs cannot collide");
var frameRoot = System.Xml.Linq.XElement.Parse("<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 345 550'/>");
Check(Enumerable.Range(1, 604).Sum(p => MushafSurahFrames.Create(p, frameRoot).Count()) == 114, "Every surah has exactly one ornamental heading frame across the mushaf");
Check(MushafSurahFrames.Create(604, frameRoot).Count() == 3 && !MushafSurahFrames.Create(3, frameRoot).Any(), "Frames appear at actual surah beginnings, including three on page 604");
using (var grouped = File.OpenRead(Path.Combine(AppContext.BaseDirectory, "601.bin.br")))
{
    var original = System.Xml.Linq.XElement.Parse(MushafPageArchive.Read(grouped, 604));
    var framed = System.Xml.Linq.XElement.Parse(MushafMarkup.PrepareSvg(original.ToString(), 604));
    var originalPaths = original.Descendants().Where(x => x.Name.LocalName == "path").Select(x => (string?)x.Attribute("d")).ToArray();
    var art = framed.Elements().Single(x => (string?)x.Attribute("id") == "p604_alm_art");
    var preserved = art.Descendants().Where(x => x.Name.LocalName == "path").Concat(framed.Elements().Where(x => (string?)x.Attribute("class") == "ayahPolygon")).Select(x => (string?)x.Attribute("d")).ToArray();
    Check(originalPaths.SequenceEqual(preserved), "Decorative frames preserve every original Quran outline and verse hit area unchanged");
}
var tawbahFrameRoot = System.Xml.Linq.XElement.Parse("<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 345 550'><path class='ayahPolygon' d='M0 39.5 L338 39.5 L338 82.25 L0 82.25Z'/></svg>");
var tawbahFrame = MushafSurahFrames.Create(187, tawbahFrameRoot).Single();
var tawbahRect = tawbahFrame.Elements().First();
Check(double.Parse((string)tawbahRect.Attribute("y")!, System.Globalization.CultureInfo.InvariantCulture) + double.Parse((string)tawbahRect.Attribute("height")!, System.Globalization.CultureInfo.InvariantCulture) <= 39, "At-Tawbah frame stays clear of the first verse despite the absent basmala");
Check(tawbahFrame.Elements().Count(e => e.Name.LocalName == "rect") == 2 && tawbahFrame.Elements().Count(e => (string?)e.Attribute("class") == "surah-spray") == 2, "Arabesque heading has two closed borders and complete botanical panels on both sides");
Check(darkMarkup.Contains("--surah-ornament:#bdad78") && darkMarkup.Contains("--surah-ornament:#24735e"), "Arabesque colors adapt to both night and daylight palettes");
Console.WriteLine($"ALL {passed} CHECKS PASSED");
